import{_ as e,o as t,c as o,ag as r}from"./chunks/framework.Dh3ZG9qC.js";const _=JSON.parse('{"title":"任务与日志","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md","lastUpdated":null}'),l={name:"guide/tasks.md"};function i(s,a,d,n,c,p){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="任务与日志" tabindex="-1">任务与日志 <a class="header-anchor" href="#任务与日志" aria-label="Permalink to &quot;任务与日志&quot;">​</a></h1><p>任务将调度方式、执行入口、参数和设备组合起来。脚本描述流程，任务决定何时、在哪运行。</p><h2 id="创建任务" tabindex="-1">创建任务 <a class="header-anchor" href="#创建任务" aria-label="Permalink to &quot;创建任务&quot;">​</a></h2><ol><li>在「任务」页新建任务，选择目标设备。</li><li>选择调度方式，内置方式为 <code>cron</code>。</li><li>选择执行器与入口。使用 YAML 自动化时，先确保 <code>gamer-yaml</code> 已安装并启用。</li><li>选择配置中的脚本，填写运行参数，保存任务。</li><li>先手动运行一次，确认设备、应用和资源正确后再启用调度。</li></ol><p>Cron 以服务端本地时区执行。浏览器关闭后任务仍由服务端调度；电脑休眠或服务停止时不会继续执行。</p><h2 id="执行状态" tabindex="-1">执行状态 <a class="header-anchor" href="#执行状态" aria-label="Permalink to &quot;执行状态&quot;">​</a></h2><p>同一设备同时只允许一个活动运行，避免不同流程争抢输入。设备忙时请求可能被拒绝，先查看当前运行。</p><p>插件缺失或停用时，依赖它的任务会保留并显示依赖缺失。恢复对应插件后，任务可重新获得执行能力。</p><p>脚本参数变化后，任务会按当前定义重新绑定：已有有效参数保留，新参数使用默认值，缺少必填值时需要补齐。不要假设历史任务保存的参数永远适用于新版脚本。</p><h2 id="查看日志与报错" tabindex="-1">查看日志与报错 <a class="header-anchor" href="#查看日志与报错" aria-label="Permalink to &quot;查看日志与报错&quot;">​</a></h2><p>「日志」页用于筛选和查看服务端运行记录。工作台状态条用于当前步骤、结果和错误的轻反馈；有定位信息时可跳到对应资源或步骤。</p><p>排查时先确认：运行对应的设备和配置、脚本保存版本、首个失败步骤与详细原因。资源在运行开始后发生变化时，错误位置可能不适用于当前编辑内容，应先核对版本。</p>',12)])])}const u=e(l,[["render",i]]);export{_ as __pageData,u as default};
